/*
 * prog39_horner.c
 *
 * Re‑implementation of the original program (prog39_horner) based on the
 * reverse‑engineered state‑machine.  The program evaluates a polynomial
 * using Horner’s method.
 *
 * Behaviour (as observed from the binary):
 *
 *   - If no arguments are supplied (argc == 1)               → prints "NO_INPUT"
 *   - If only one argument is supplied (argc == 2)          → prints "EMPTY"
 *   - If more than 13 coefficients are supplied
 *     (i.e. argc > 14, because argv[0] is the program name) → prints "OUT_OF_RANGE"
 *   - If the first argument (the value of x) is not a valid
 *     decimal integer                                         → prints "BAD_INPUT"
 *   - If any coefficient is not a valid decimal integer      → prints "BAD_INPUT"
 *   - Otherwise evaluates the polynomial
 *
 * The polynomial is given by the coefficients in the order they appear
 * on the command line (highest‑degree coefficient first).  Horner’s rule
 *
 *        result = a0;
 *        for i = 1 .. n-1
 *            result = result * x + a_i;
 *
 * is used, where `x` is the first argument and `a_i` are the remaining
 * arguments.  The final result is printed with `printf("%lld\n", result);`.
 *
 * All messages are printed with `puts`, which appends a newline.
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* 1. Argument count checks */
    if (argc < 2) {                     /* no x supplied */
        puts("NO_INPUT");
        return 0;
    }
    if (argc == 2) {                    /* only x, no coefficients */
        puts("EMPTY");
        return 0;
    }
    if (argc > 14) {                    /* more than 12 coefficients */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 2. Parse x (the first user‑supplied argument) */
    char *endptr;
    long x = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {            /* conversion failed */
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. Parse coefficients */
    int coeff_cnt = argc - 2;           /* number of coefficients */
    long coeffs[13];                    /* enough for the allowed maximum */

    for (int i = 0; i < coeff_cnt; ++i) {
        long v = strtol(argv[2 + i], &endptr, 10);
        if (endptr == argv[2 + i]) {    /* conversion failed */
            puts("BAD_INPUT");
            return 0;
        }
        coeffs[i] = v;
    }

    /* 4. Horner evaluation */
    long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeffs[i];
    }

    /* 5. Output the result */
    printf("%lld\n", result);
    return 0;
}
